import React, { useEffect, useRef, useState } from 'react';
import './Banner.css';
import textImage from './image/text.png';
import abdou from './image/abdou.png';
import scrollGif from './image/scroll.gif';

function Banner() {
  const bannerRef = useRef(null);
  const imageContainerRef = useRef(null);
  const scrollingTextRef = useRef(null);
  const [isHidden, setIsHidden] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const scrollPosition = window.scrollY;
      const windowHeight = window.innerHeight;

      // Banner Scaling
      const scaleFactor = Math.max(1, Math.min(2.2, 1 + (scrollPosition / windowHeight) * 0.9));
      const textScaleFactor = Math.max(0.7, Math.min(1, 1 - (scrollPosition / windowHeight) * 0.3));

      if (scrollPosition > windowHeight * 0.5) {
        setIsHidden(true);
      } else {
        setIsHidden(false);
      }

      if (bannerRef.current) bannerRef.current.style.transform = `scale(${scaleFactor})`;
      if (imageContainerRef.current) imageContainerRef.current.style.transform = `translate(-50%, -50%) scale(${scaleFactor})`;
      if (scrollingTextRef.current) scrollingTextRef.current.style.transform = `translateY(-50%) scale(${textScaleFactor})`;
    };

    const animationFrameHandler = () => {
      handleScroll();
      requestAnimationFrame(animationFrameHandler);
    };

    animationFrameHandler();
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className={`banner ${isHidden ? 'hidden' : ''}`} ref={bannerRef}>
 <div className="marquee-container">
  <div className="marquee">
    <img src={textImage} alt="scrolling-text" />
    <img src={textImage} alt="scrolling-text" />
    <img src={textImage} alt="scrolling-text" />
    <img src={textImage} alt="scrolling-text" />
    <img src={textImage} alt="scrolling-text" />
    <img src={textImage} alt="scrolling-text" />
  </div>
</div>


      <div className="static-image-container" ref={imageContainerRef}>
        <img src={abdou} alt="Flying Superman Abdou" />
      </div>
      <div className="scroll-down-indicator">
        <img src={scrollGif} alt="Scroll Down" />
        <p className="scroll-text">Scroll Down</p>
      </div>
    </div>
  );
}

export default Banner;
